"""Build self-contained, visually rich HTML pages for the Arena file preview.
The preview iframe does not fetch local CSS/JS/images, so every page embeds its visual system and
all raster assets as data URIs. The same pages also work on regular static hosting.
"""
from pathlib import Path
import base64
import re

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT
IMG = ROOT / "assets" / "inline-optimized"


def data_image(name: str) -> str:
    raw = (IMG / f"{name}.jpg").read_bytes()
    encoded = base64.b64encode(raw).decode("ascii")
    return f"data:image/jpeg;base64,{encoded}"

IMAGES = {p.stem: data_image(p.stem) for p in IMG.glob("*.jpg")}
# The user-supplied collector photograph will be used automatically as soon as its optimised replacement exists.
HEATING_KEY = "heating-manifold-valtec1" if "heating-manifold-valtec1" in IMAGES else "heating-manifold-valtec"

