CONSENT_MODAL = r'''<div class="modal-overlay" id="consent-modal" role="dialog" aria-modal="true" aria-labelledby="consent-title"><div class="consent-modal"><p class="eyebrow">Персональные данные</p><h3 id="consent-title">Подтверждение согласия</h3><p id="consent-copy">Перед отправкой запроса необходимо подтвердить согласие на обработку персональных данных.</p><div class="buttons"><button class="btn" id="consent-confirm" type="button">Подписать и отправить</button><button class="btn line" id="consent-cancel" type="button">Отмена</button></div></div></div>'''

INLINE_SCRIPT = r'''<script>
window.CLIMATCOMFORT_CONFIG = {
  mode: 'demo',
  bitrix24: {
    enabled: false,
    // В production укажите защищённый серверный proxy endpoint, а не публичный webhook Bitrix24.
    proxyEndpoint: '/api/bitrix24/lead',
    entity: 'crm.lead.add',
    defaultSource: 'climatcomfort39.ru'
  }
};
(function () {
  const modal = document.getElementById('consent-modal');
  const copy = document.getElementById('consent-copy');
  const confirm = document.getElementById('consent-confirm');
  const cancel = document.getElementById('consent-cancel');
  let pendingForm = null;

  function openModal(text, form, needsCheck) {
    pendingForm = form || null;
    copy.textContent = text;
    confirm.textContent = needsCheck ? 'Вернуться к согласию' : 'Подписать и отправить';
    confirm.dataset.needsCheck = needsCheck ? '1' : '0';
    modal.classList.add('open');
    confirm.focus();
  }
  function closeModal() { modal.classList.remove('open'); pendingForm = null; }
  function completeSubmission(form) {
    const status = form.querySelector('.status');
    const payload = {
      title: form.dataset.b24Source || window.location.pathname,
      source: form.dataset.b24Source || window.CLIMATCOMFORT_CONFIG.bitrix24.defaultSource,
      fields: Object.fromEntries(new FormData(form).entries()),
      consent: { accepted: true, policy: 'privacy.html', acceptedAt: new Date().toISOString() }
    };
    const b24 = window.CLIMATCOMFORT_CONFIG.bitrix24;
    if (window.CLIMATCOMFORT_CONFIG.mode === 'bitrix24' && b24.enabled && b24.proxyEndpoint) {
      fetch(b24.proxyEndpoint, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) })
        .then(r => { if (!r.ok) throw new Error('CRM request failed'); return r.json(); })
        .then(() => { status.textContent = 'Согласие подтверждено. Запрос передан в CRM Битрикс24.'; form.reset(); })
        .catch(() => { status.textContent = 'Согласие подтверждено. Не удалось передать заявку в CRM; свяжитесь с нами по телефону или e-mail.'; });
    } else {
      status.textContent = 'Согласие подтверждено. В демо-версии заявка не передаётся в CRM. После подключения защищённого API Битрикс24 этот же сценарий создаст лид.';
      form.reset();
    }
  }
  document.querySelectorAll('form[data-b24-form], form[data-demo]').forEach(form => {
    form.addEventListener('submit', event => {
      event.preventDefault();
      const consent = form.querySelector('[data-consent]');
      if (!consent || !consent.checked) {
        openModal('Для подписания соглашения отметьте согласие на обработку персональных данных в форме. Без него запрос не будет отправлен.', form, true);
        return;
      }
      openModal('Нажимая «Подписать и отправить», вы подтверждаете согласие на обработку указанных персональных данных для ответа на запрос и подготовки предложения. Полный текст размещён в Политике обработки персональных данных.', form, false);
    });
  });
  confirm.addEventListener('click', () => {
    if (!pendingForm) return closeModal();
    if (confirm.dataset.needsCheck === '1') {
      const form = pendingForm;
      closeModal();
      form.querySelector('[data-consent]')?.focus();
      return;
    }
    const form = pendingForm;
    closeModal();
    completeSubmission(form);
  });
  cancel.addEventListener('click', closeModal);
  modal.addEventListener('click', event => { if (event.target === modal) closeModal(); });
  document.addEventListener('keydown', event => { if (event.key === 'Escape') closeModal(); });
})();
</script>'''


def header(current: str) -> str:
    links = ''.join(f'<a class="{"active" if key == current else ""}" href="{url}">{name}</a>' for key, url, name in PAGES)
    mob = ''.join(f'<a href="{url}">{name}</a>' for _, url, name in PAGES)
    return f'''<div class="topline"></div><a class="skip" href="#content">К содержанию</a><header class="header"><div class="wrap nav">{logo()}<nav class="menu" aria-label="Основное меню">{links}</nav><button class="menu-btn" type="button" onclick="document.querySelector('.mobile-menu').classList.toggle('open')">Меню</button></div><nav class="wrap mobile-menu" aria-label="Мобильное меню">{mob}</nav></header>'''


def footer() -> str:
    return f'''<footer class="footer"><div class="wrap"><div class="footgrid"><div class="intro">{logo()}<p>Кондиционирование, вентиляция, отопление, автоматизация и ОВКВ-проектирование для Калининграда и области.</p></div><div><h4>Решения</h4><a href="services.html#air">Кондиционирование</a><a href="services.html#vent">Вентиляция</a><a href="services.html#heat">Отопление</a><a href="services.html#auto">Автоматика</a></div><div><h4>Партнёрство</h4><a href="partners.html">Дизайнерам</a><a href="partners.html#org">ГИПам</a><a href="journal.html">Журнал</a></div><div><h4>Старт проекта</h4><a href="contacts.html">Получить расчёт</a><a href="contacts.html">Калининград и область</a><a href="privacy.html">Политика данных</a></div></div><div class="footline"><span>© 2026 КлиматКомфорт39 · Михеева О.В. ИНН 390203089521</span></div></div></footer>'''


def doc(title: str, description: str, current: str, body: str) -> str:
    return f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{description}"><meta name="theme-color" content="#000000"><title>{title}</title><style>{CSS}</style></head><body>{header(current)}<main id="content">{body}</main>{footer()}{CONSENT_MODAL}{INLINE_SCRIPT}</body></html>'''


def hero(kicker: str, title: str, lead: str, image: str, action: str, color: str = "", code: str = "01") -> str:
    secondary_href = "#partner-ux" if code == "B2B" else "partners.html"
    return f'''<section class="hero {color}"><div class="wrap hero-inner"><div class="hero-copy"><p class="eyebrow light">{kicker}</p><h1>{title}</h1><p class="lead">{lead}</p><div class="buttons">{action}<a class="btn line" href="{secondary_href}">Для дизайнеров {icon('arrow')}</a></div></div><div class="hero-art"><img class="hero-photo" src="{IMAGES[image]}" alt="Инженерные системы в современном интерьере"><span class="orb a"></span><span class="orb b"></span><div class="floating-card"><span class="chip">Сначала — логика</span><b>Воздух, тепло и автоматика не должны спорить друг с другом.</b><span>Согласуем систему до скрытых работ и чистовой отделки.</span></div><div class="hero-code">{code}</div></div></div></section>'''


def home() -> str:
    body = hero("Калининград · область · инженерный комфорт", "Комфорт<br>без визуального<br>шума.", "Проектируем воздух, тепло и управление так, чтобы интерьер оставался цельным, монтаж — предсказуемым, а жизнь в доме — по-настоящему лёгкой.", "hero-premium-home", f"<a class='btn pink' href='contacts.html'>Обсудить объект {icon('arrow')}</a>", "", "39")
    body += f'''<section class="statbar"><div class="wrap"><div class="stats"><div class="stat"><b>2</b><span>бригады по кондиционированию — для плановой работы и сезона</span></div><div class="stat"><b>ОВКВ</b><span>проектировщик для решений до начала отделки</span></div><div class="stat"><b>Тепло</b><span>отдельная компетенция по тёплому полу и отоплению</span></div><div class="stat"><b>Smart</b><span>автоматика, которая следует вашему ритму</span></div></div></div></section><div class="marquee"><span>кондиционирование</span><span>вентиляция</span><span>отопление</span><span>автоматика</span><span>ОВКВ-проектирование</span><span>кондиционирование</span><span>вентиляция</span></div>'''
    service_cards = [
        ("01 · воздух", "Кондиционирование", "Тихое охлаждение, обогрев и чистая интеграция в готовое пространство.", "hisense-sensation-carbon", "air"),
        ("02 · свежесть", "Вентиляция", "Распределение воздуха, доступы и низкий шум — по планировке дома.", "ventilation-plenum", "vent"),
        ("03 · тепло", "Отопление", "Тёплый пол, радиаторы и понятная логика контуров для стабильного режима.", "zehnder-vertical-radiator", "heat"),
        ("04 · логика", "Автоматика", "Сценарии температуры и воздуха, которые понятны владельцу, а не только инженеру.", "bim-engineering-design", "auto"),
    ]
    card_html = ''.join(f'''<a class="card art" href="services.html#{anchor}"><img src="{IMAGES[img]}" alt="{title}"><div class="card-content"><span class="tag">{num}</span><h3>{title}</h3><p>{text}</p><span class="more">Посмотреть решение {icon('arrow')}</span></div></a>''' for num,title,text,img,anchor in service_cards)
    body += f'''<section class="section"><div class="wrap"><div class="section-head"><div><p class="eyebrow">Собранная инженерия</p><h2>Четыре слоя —<br>один сценарий жизни.</h2></div><p class="lead">Не начинаем с витрины оборудования. Сначала разбираем планировку, свет, мебель, привычки семьи и этап ремонта. Поэтому решения не конфликтуют в самом важном месте — на объекте.</p></div><div class="cards">{card_html}</div></div></section>'''
    body += f'''<section class="section blue"><div class="wrap split"><div class="visual-stack"><img class="big" src="{IMAGES['clean-installation1']}" alt="Бережный монтаж кондиционера в интерьере"><img class="mini" src="{IMAGES['service-care1']}" alt="Сервисное обслуживание кондиционера"><span class="sticker">сначала<br>проверяем<br>план</span></div><div><p class="eyebrow">Не «установим», а согласуем</p><h2>Инженерия должна облегчать ремонт, а не создавать ещё один фронт работ.</h2><p class="lead">В хорошем интерьере нет случайных коробов, неожиданных решёток и спорных мест для блока. Есть заранее принятая логика, которой удобно следовать всем участникам проекта.</p><ul class="ticks"><li>{icon('check','ico tick')}<span><b>Стыкуем с дизайн-проектом.</b> Высоты потолков, мебель, свет, технические зоны и будущий сервис проверяются до монтажа.</span></li><li>{icon('check','ico tick')}<span><b>Показываем состав работ.</b> Оборудование, монтаж, материалы и особенности объекта не смешиваются в одну непонятную цифру.</span></li><li>{icon('check','ico tick')}<span><b>Передаём систему человеку.</b> После запуска объясняем логику и базовый уход, а не исчезаем после установки.</span></li></ul><a class="btn" href="about.html">Как работает команда {icon('arrow')}</a></div></div></section>'''
    body += f'''<section class="section"><div class="wrap"><div class="section-head"><div><p class="eyebrow">Инженерная ДНК</p><h2>В центре системы — не оборудование. В центре — человек.</h2></div><p class="lead">Технологии нужны не ради панели управления на стене. Они должны поддерживать сон, работу, отдых, тишину и свободу не думать о температуре каждые полчаса.</p></div><div class="bento"><div class="bento-item navy">{icon('wind')}<h3>Свежесть</h3><p>Вентиляция отвечает за управляемый воздухообмен, а не за «проветрить когда-нибудь».</p></div><div class="bento-item pink">{icon('snow')}<h3>Точность</h3><p>Кондиционирование работает там, где действительно нужно, и не дует в любимое место на диване.</p></div><div class="bento-item cyan">{icon('heat')}<h3>Ровное тепло</h3><p>Отопительные контуры и приборы становятся частью целого, а не отдельной проблемой.</p></div></div></div></section>'''
    body += f'''<section class="section dark"><div class="wrap split"><div class="diagram"><p class="eyebrow light">Инфографика</p><h2>Одна система.<br>Четыре роли.</h2><div class="diagram-grid"><div class="diagram-box">01<b>Воздух</b>Приток, вытяжка, фильтрация</div><div class="diagram-box">02<b>Температура</b>Охлаждение и мягкий обогрев</div><div class="diagram-box">03<b>Тепло</b>Пол, радиаторы, гидравлика</div><div class="diagram-box">04<b>Логика</b>Сценарии, зоны, управление</div></div><div class="center">Комфорт<br>для жизни</div></div><div><p class="eyebrow light">Прямой ответ</p><h2>Кондиционер не заменяет вентиляцию.</h2><p class="lead" style="color:#d2e4f3">Сплит-система в основном меняет температуру воздуха внутри комнаты. За свежий приток и удаление воздуха отвечает вентиляция. Когда эти системы проектируются вместе, дом ощущается совсем иначе.</p><div class="buttons"><a class="btn lime" href="journal.html#vent">Почему это важно {icon('arrow')}</a></div></div></div></section>'''
    body += f'''<section class="section"><div class="wrap"><div class="partner-band"><img src="{IMAGES['designer-partnership']}" alt="Дизайнер и инженер согласовывают проект"><p class="eyebrow light">Дизайнерам и ГИПам</p><h2>Идея интерьера остаётся цельной, когда инженер подключается вовремя.</h2><p class="lead">Проверяем технические зоны, даём 2–3 реализуемых сценария, фиксируем изменения и берём на себя монтажный контур. Это не ещё один подрядчик — это понятный способ защитить проект.</p><div class="buttons"><a class="btn lime" href="partners.html">Посмотреть формат работы {icon('arrow')}</a></div></div></div></section>'''
    body += f'''<section class="section pink-bg"><div class="wrap"><div class="section-head"><div><p class="eyebrow">Визуальный выбор</p><h2>Техника может быть частью интерьера.</h2></div><p class="lead">Подбираем не «самую дорогую» модель, а ту, что соответствует сценарию, уровню шума, дизайну и будущему обслуживанию.</p></div><div class="equipment"><article class="equip"><img src="{IMAGES['hisense-sensation-carbon']}" alt="Официальное изображение Hisense Sensation Slider Pro Carbon"><div class="equip-body"><span class="num">КОНДИЦИОНИРОВАНИЕ</span><h3>SENSATION / CARBON</h3><p>Визуальный сценарий для графитового интерьера и точного управления потоком воздуха.</p></div></article><article class="equip"><img src="{IMAGES[HEATING_KEY]}" alt="Узел отопления"><div class="equip-body"><span class="num">ОТОПЛЕНИЕ</span><h3>Гидравлика без хаоса</h3><p>Смесительные узлы уровня Valtec VT.Combi и отдельные контуры под режим дома.</p></div></article><article class="equip"><img src="{IMAGES['zehnder-vertical-radiator']}" alt="Вертикальный радиатор"><div class="equip-body"><span class="num">ИНТЕРЬЕР</span><h3>Вертикальный ритм</h3><p>Радиаторы уровня Zehnder, когда отопительный прибор становится архитектурной деталью.</p></div></article></div><p class="small-note">Официальное изображение серии Hisense SENSATION SLIDER PRO CARBON использовано с продуктовой страницы Hisense. Остальные концептуальные визуалы созданы для прототипа. Точные модели, комплектации и наличие фиксируются в индивидуальном предложении.</p></div></section>'''
    body += f'''<section class="section blue"><div class="wrap split"><div><p class="eyebrow">Видео для сайта и соцсетей</p><h2>20 секунд, чтобы почувствовать подход.</h2><p class="lead">Ролик показывает путь от тихого интерьера к воздуху, чистому монтажу и совместной работе инженера с дизайнером. Встроенный файл находится в папке <b>media</b>.</p><div class="buttons"><a class="btn" href="media/promo-climatcomfort39.mp4">Открыть MP4 {icon('play')}</a></div></div><a class="video-card" href="media/promo-climatcomfort39.mp4" aria-label="Открыть промо-ролик"><div class="video-poster"><img src="{IMAGES['hero-premium-home']}" alt="Превью промо-ролика КлиматКомфорт39"><span class="video-play">{icon('play')} Смотреть фильм</span></div><div class="video-caption"><span>20 сек · H.264 · 16:9</span><span>AI-assisted visual story</span></div></a></div></section>'''
    body += f'''<section class="section dark"><div class="wrap faq"><div><p class="eyebrow light">AIEO · быстрые ответы</p><h2>Вопросы, с которых начинается комфорт.</h2><p class="lead" style="color:#c7d9e7">Ясные ответы полезны и человеку, и поисковым системам. Поэтому сначала отвечаем прямо — затем объясняем условия и нюансы.</p></div><div class="faq-list"><details class="faq-item" open><summary>Когда закладывать трассы кондиционера?</summary><div><b>Лучше до чистовой отделки:</b> после утверждения мебели, потолков и планировки. Тогда трассы, дренаж и питание можно скрыть без случайных коробов.</div></details><details class="faq-item"><summary>Можно ли установить кондиционер после ремонта?</summary><div><b>Да, можно.</b> Но маршрут, защита поверхностей, внешний блок и видимая часть коммуникаций должны быть оценены до начала работ.</div></details><details class="faq-item"><summary>Что получает дизайнер от инженерной команды?</summary><div><b>Обратную связь по реализуемости:</b> высоты, пересечения, сервисные зоны и варианты решения до того, как они станут переделками.</div></details><details class="faq-item"><summary>Нужно ли обслуживать рабочий кондиционер?</summary><div><b>Да, профилактически.</b> Сервис помогает сохранить чистоту теплообменника и вовремя заметить отклонения.</div></details></div></div></section>'''
    body += f'''<section class="section tight"><div class="wrap"><div class="cta"><div><p class="eyebrow">Следующий шаг</p><h2>Пришлите планировку. Вернёмся не с каталогом — с логикой решения.</h2><p>Можно начать с дизайн-проекта, PDF, визуализации или простой задачи в двух предложениях.</p></div><a class="btn white" href="contacts.html">Получить расчёт {icon('arrow')}</a></div></div></section>'''
    return doc("КлиматКомфорт39 — комфорт без визуального шума", "Инженерные системы для интерьера: кондиционирование, вентиляция, отопление, автоматика и ОВКВ в Калининграде.", "home", body)


def services() -> str:
    body = '''<section class="page-top blue"><div class="wrap"><p class="crumb">Главная / Решения</p><p class="eyebrow light">Кондиционирование · вентиляция · тепло · автоматика</p><h1>Не набор техники.<br>Инженерный сценарий.</h1><p class="lead">Согласуем воздух, тепло и управление с архитектурой пространства. В результате у каждого устройства есть причина, место, доступ и понятная роль.</p></div></section>'''
    body += f'''<section class="section"><div class="wrap"><nav class="service-nav"><a href="#air">01 Кондиционирование</a><a href="#vent">02 Вентиляция</a><a href="#heat">03 Отопление</a><a href="#auto">04 Автоматика и ОВКВ</a><a href="#price">Ориентиры</a></nav><div class="section-head"><div><p class="eyebrow">Четыре направления</p><h2>Выбираем не уровень «премиум». Выбираем правильный уровень системы.</h2></div><p class="lead">Для однокомнатной квартиры и дома на несколько этажей нужны разные решения. Общим остаются расчёт, уважение к отделке и прозрачный состав работ.</p></div>'''
    blocks = [
        ("air","01 · Кондиционирование","Точная температура. Тихий воздух. Без случайных коробов.","Подбираем тип системы, мощность, место блоков, трассу, дренаж и питание. Отдельно разбираем монтаж на стадии ремонта и в готовом интерьере.","clean-installation",[("snow","Комфортный поток"),("wind","Тихий режим"),("doc","Прозрачный состав"),("clock","Два этапа ремонта")]),
        ("vent","02 · Вентиляция","Свежий воздух не должен быть заметен — только ощутим.","Проектируем воздухораспределение так, чтобы оно не конфликтовало с потолками, светом, акустикой, мебелью и будущим доступом к фильтрам.","ventilation-plenum",[("wind","Пленумы и решётки"),("shield","Акустический комфорт"),("tool","Сервисные доступы"),("home","Сценарий дома")]),
        ("heat","03 · Отопление","Ровное тепло с понятной гидравликой и эстетикой.","Собираем тёплый пол, радиаторные контуры, смесительные узлы и регулирование как единую систему, а не набор отдельных компонентов.","heating-manifold-valtec",[("heat","Водяной тёплый пол"),("ruler","Дизайнерские радиаторы"),("bolt","Смесительные узлы"),("brain","Зональное управление")]),
        ("auto","04 · Автоматика и ОВКВ","Сначала проектируем логику. Потом она незаметно работает.","Готовим инженерную схему и координируем разделы, чтобы дизайнер, монтажники и владелец говорили об одном объекте без догадок на площадке.","bim-engineering-design",[("doc","ОВКВ-проект"),("brain","Сценарии"),("bolt","Контроль параметров"),("ruler","Меньше коллизий")]),
    ]
    for i,(anchor,num,title,text,img,micros) in enumerate(blocks):
        photo = f'<img class="photo" src="{IMAGES[img]}" alt="{title}">'
        micro = ''.join(f'<div class="micro">{icon(k)}<b>{t}</b><br><span style="font-weight:400">'+({"Комфортный поток":"Расположение блока и жалюзи не мешает отдыху и работе.","Тихий режим":"Учитываем спальни, детские и вибрацию наружного блока.","Прозрачный состав":"Сразу разделяем монтаж, материалы и условия объекта.","Два этапа ремонта":"Коммуникации до отделки, внутренний блок — после.","Пленумы и решётки":"Распределение воздуха по реальному расходу и архитектуре.","Акустический комфорт":"Трассы и узлы не должны становиться шумовым фоном.","Сервисные доступы":"Ключевые узлы обслуживаются без вскрытия дорогой отделки.","Сценарий дома":"Спальни, кухня, санузлы и гардеробные получают свою логику.","Водяной тёплый пол":"Контуры и температура связаны с покрытием и теплопотерями.","Дизайнерские радиаторы":"Вертикальные решения становятся частью интерьера.","Смесительные узлы":"Режим низкотемпературных контуров контролируется правильно.","Зональное управление":"Температура следует назначению, а не усреднённой схеме.","ОВКВ-проект":"Планы, маршруты и логика для выполнимой реализации.","Сценарии":"Оборудование может следовать времени и выбранному режиму.","Контроль параметров":"Только полезные показатели для комфортного управления.","Меньше коллизий":"Координация до монтажа снижает решения «на глаз»."}[t])+ '</span></div>' for k,t in micros)
        copy = f'<div class="service-copy"><p class="eyebrow">{num}</p><h2>{title}</h2><p>{text}</p><div class="micro-grid">{micro}</div></div>'
        body += f'<article class="service-block{" reverse" if i%2 else ""}" id="{anchor}">{copy if i%2 else photo}{photo if i%2 else copy}</article>'
    body += f'''</div></section>'''
    body += f'''<section class="section pink-bg"><div class="wrap"><div class="section-head"><div><p class="eyebrow">Кондиционирование · визуальный слой</p><h2>Две серии — два характера интерьера.</h2></div><p class="lead">Модели подбираются не по картинке. Но визуальный язык, шум, поток и способы управления действительно влияют на ежедневное впечатление от пространства.</p></div><div class="models"><article class="model"><img src="{IMAGES['hisense-sensation-carbon']}" alt="Официальное изображение Hisense Sensation Slider Pro Carbon"><div><span class="num">ГРАФИТ / INTELLIGENT AIRFLOW</span><h3>SENSATION SLIDER PRO CARBON</h3><p>Серия Hisense с выразительной панелью, встроенным Wi‑Fi, интеллектуальным управлением воздушным потоком и тихой работой — по данным производителя.</p><div class="pills"><span class="pill">инвертор</span><span class="pill">Wi‑Fi</span><span class="pill">Smart Eye</span><span class="pill">от 18 дБ(A)</span></div></div></article><article class="model"><img src="{IMAGES['hisense-vibe-champagne']}" alt="Концептуальная визуализация Hisense Vibe Champagne"><div><span class="num">ШАМПАНЬ / 4D AIR</span><h3>VIBE PRO CHAMPAGNE EU</h3><p>Серия Hisense в тёплой металлической отделке: встроенный Wi‑Fi, 4D AUTO Air, ионизация и многоскоростной вентилятор — по данным производителя.</p><div class="pills"><span class="pill">класс A++</span><span class="pill">4D AUTO Air</span><span class="pill">Wi‑Fi</span><span class="pill">от 21 дБ(A)</span></div></div></article></div><p class="small-note">AI-визуализации не являются официальными карточками товара. Точная серия, комплектация, наличие и условия подтверждаются в индивидуальном предложении.</p></div></section>'''
    body += f'''<section class="section dark" id="price"><div class="wrap"><div class="section-head"><div><p class="eyebrow light">Ориентиры инвестиций</p><h2>Цена понятна, когда понятен уровень решения.</h2></div><p class="lead" style="color:#c6d9e8">Финальный расчёт зависит от площади, стадии ремонта, фасада, трасс, доступа и оборудования. Эти ориентиры — навигатор, а не публичная оферта.</p></div><div class="price-grid"><article class="price"><span class="tag" style="border-color:var(--line);color:var(--blue)">Точечная задача</span><h3>Комфорт в одной зоне</h3><p class="amount">от 60 000 ₽</p><p>Инверторная сплит-система с профессиональным монтажом для типовой комнаты; состав уточняется по объекту.</p><ul><li>Подбор мощности</li><li>Монтаж и запуск</li><li>Инструктаж владельца</li></ul></article><article class="price featured"><span class="tag">Рекомендуемый путь</span><h3>Проектный комфорт</h3><p class="amount">от 30 000 ₽</p><p>Инженерная концепция вентиляции / кондиционирования с привязкой к планировке и дальнейшей смете.</p><ul><li>Техническое задание</li><li>Схема и координация</li><li>Основа для реализации</li></ul></article><article class="price"><span class="tag" style="border-color:var(--line);color:var(--blue)">Комплексная инженерия</span><h3>Дом или большой интерьер</h3><p class="amount">по расчёту</p><p>Вентиляция, отопление, охлаждение и автоматика как согласованный набор систем.</p><ul><li>Несколько разделов</li><li>Работа с дизайном</li><li>Пусконаладка и сервис</li></ul></article></div></div></section>'''
